{"REPEAT","reg=outlaw|st=friendly",{"Sure, no problem, I'll say it again"}},
{"REPEAT","reg=law|st=neutral,careful",{"I'll repeat that once more, pay attention","Say again? Louder, please"}},
{"REPEAT","reg=law|st=hostile",{"Listen carefully, I won't repeat it!"}},
{"REPEAT","reg=law|st=friendly",{"Of course, let me say it again, slower"}},
{"REPEAT","reg=military|st=neutral,careful",{"I repeat, pay attention"}},
{"REPEAT","reg=military|st=hostile",{"I will not repeat myself!"}},
{"REPEAT","reg=military|st=friendly",{"Sure, friend, let me repeat that"}},
{"REPEAT","role=soldier_green|st=neutral,careful",{"What? Sorry! I didn't hear! I was thinking about something else, sorry!"}},
{"REPEAT","role=militia|st=neutral,careful",{"Say again, neighbor? My hearing isn't what it was"}},
{"REPEAT","role=militia|st=friendly",{"Sure, I'll say it plainer"}},
